import{_ as e,o as d,c as a,ag as r}from"./chunks/framework.Dh3ZG9qC.js";const _=JSON.parse('{"title":"服务端配置","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"reference/configuration.md","lastUpdated":null}'),o={name:"reference/configuration.md"};function c(s,t,i,n,l,p){return d(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="服务端配置" tabindex="-1">服务端配置 <a class="header-anchor" href="#服务端配置" aria-label="Permalink to &quot;服务端配置&quot;">​</a></h1><p>源码开发默认读取 <code>server/config.toml</code>。可从仓库的 <a href="https://github.com/jesongit/gamer/blob/main/server/config.example.toml" target="_blank" rel="noreferrer">config.example.toml</a> 创建本机配置；该文件不提交版本控制。</p><h2 id="常用选项" tabindex="-1">常用选项 <a class="header-anchor" href="#常用选项" aria-label="Permalink to &quot;常用选项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>用途</th></tr></thead><tbody><tr><td><code>port</code></td><td>HTTP 监听端口，默认 8443</td></tr><tr><td><code>data_dir</code></td><td>数据根目录，源码开发通常为 <code>./data</code></td></tr><tr><td><code>adb_path</code></td><td>ADB 命令名或绝对路径</td></tr><tr><td><code>ffmpeg_path</code></td><td>FFmpeg 命令名或绝对路径；视频功能还需要 ffprobe</td></tr><tr><td><code>scrcpy_server</code></td><td>与当前宿主匹配的 scrcpy server 文件</td></tr><tr><td><code>fps</code></td><td>默认帧率上限</td></tr><tr><td><code>bitrate_mbps</code></td><td>视频编码码率，过高可能增大链路负担</td></tr><tr><td><code>idle_power_secs</code></td><td>空闲低功耗等待时长，0 关闭</td></tr><tr><td><code>log_retain_days</code></td><td>文件日志保留天数，0 不自动清理</td></tr><tr><td><code>compute_max_concurrency</code></td><td>视觉等计算任务并发上限，0 自动选择</td></tr></tbody></table><p>带目录的相对工具路径和 <code>data_dir</code> 相对配置文件位置解析；裸命令名通过 PATH 查找。scrcpy 等应用资产受 <code>GAMER_APP_DIR</code> 控制，未指定时遵循服务端工作目录。手动运行服务时先进入 <code>server/</code>。</p><h2 id="认证" tabindex="-1">认证 <a class="header-anchor" href="#认证" aria-label="Permalink to &quot;认证&quot;">​</a></h2><p>管理员账号为 <code>admin</code>，没有预设密码。默认开发模式下，可在本机首次设置密码，或使用 <code>GAMER_ADMIN_PASSWORD</code>。</p><p><code>[auth].password_hash</code> 保存 Argon2id PHC，不填写明文。生产模式不使用开发明文环境变量，必须提供有效配置；会话通过 Cookie 认证。<code>session_abs_secs</code>、<code>session_idle_secs</code> 控制会话时限，<code>login_max_fails</code>、<code>login_window_secs</code> 控制失败限流。</p><p><code>GAMER_ADMIN_TOKEN</code> 是本机管理通道使用的令牌，与浏览器登录密码不同；由启动工具管理时无需把它填入网页。</p><h2 id="webrtc-网络" tabindex="-1">WebRTC 网络 <a class="header-anchor" href="#webrtc-网络" aria-label="Permalink to &quot;WebRTC 网络&quot;">​</a></h2><p>默认同机 / 局域网直接使用 host candidate，无内置 STUN/TURN。固定外部可达地址和端口时可配置：</p><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rtc_external_ip = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;192.168.1.10&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rtc_udp_port = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3478</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rtc_external_port = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>示例表示浏览器访问外部 UDP 50000，映射到服务端绑定的 UDP 3478。地址与端口应改为实际网络；外部端口与绑定端口相同时，<code>rtc_external_port</code> 可为 0。</p><p>配置固定 <code>rtc_udp_port</code> 时需同时提供有效 <code>rtc_external_ip</code>。端口变更需要重启服务，网络设备和防火墙也必须允许对应流量。</p><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>用途</th></tr></thead><tbody><tr><td><code>GB_CONFIG</code></td><td>指定配置文件位置</td></tr><tr><td><code>GB_LOG</code></td><td>文件日志基准路径或日志输出方式</td></tr><tr><td><code>GAMER_PROFILE</code></td><td>开发或生产配置策略</td></tr><tr><td><code>GAMER_APP_DIR</code></td><td>应用资产目录</td></tr><tr><td><code>GAMER_DATA_DIR</code></td><td>覆盖数据目录</td></tr><tr><td><code>GAMER_ADB_PATH</code>、<code>GAMER_FFMPEG_PATH</code></td><td>覆盖工具路径</td></tr><tr><td><code>GAMER_SCRCPY_SERVER</code></td><td>覆盖 scrcpy server 路径</td></tr></tbody></table><p>Launcher 会按安装布局注入所需路径。配置内容错误时应修复后重启，不要通过删除数据目录来规避启动错误。</p>`,17)])])}const b=e(o,[["render",c]]);export{_ as __pageData,b as default};
